mapper.select:
SELECT
    *
FROM
    ha_workspace_file
WHERE
    owner_key = #{ownerKey}
    AND agent_key = #{agentKey}
    AND scope_key = #{scopeKey}
    AND path_hash = #{pathHash}

SELECT
    *
FROM
    ha_workspace_file
WHERE
    owner_key = #{ownerKey}
    AND agent_key = #{agentKey}
    AND scope_key = #{scopeKey}
    AND file_path LIKE #{filePath}
ORDER BY
    file_path
LIMIT
    #{limit}
OFFSET
    #{offset}

SELECT
    COUNT(*)
FROM
    ha_workspace_operation
WHERE
    owner_key = #{ownerKey}
    AND agent_key = #{agentKey}
    AND scope_key = #{scopeKey}
    AND path_hash = #{pathHash}
    AND operation_id = #{operationId}

mapper.delete:
DELETE FROM ha_workspace_file
WHERE
    owner_key = #{ownerKey}
    AND agent_key = #{agentKey}
    AND scope_key = #{scopeKey}
    AND path_hash = #{pathHash}
    AND version = #{version}

mapper.update:
UPDATE ha_workspace_file
SET
    content_ref = #{contentRef},
    checksum_sha256 = #{checksumSha256},
    size_bytes = #{sizeBytes},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE
    owner_key = #{ownerKey}
    AND agent_key = #{agentKey}
    AND scope_key = #{scopeKey}
    AND path_hash = #{pathHash}
    AND version = #{version}
